resource "google_compute_firewall" "allow_https_web" {
  name      = "allow-https-web"
  network   = "prod-vpc"
  direction = "INGRESS"

  allow {
    protocol = "tcp"
    ports    = ["443"]
  }

  source_ranges = ["0.0.0.0/0"]
  target_tags   = ["web"]
}

resource "google_compute_firewall" "allow_iap_ssh" {
  name        = "allow-iap-ssh"
  network     = "prod-vpc"
  direction   = "INGRESS"
  description = "SSH via IAP only - do not delete"

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  source_ranges = ["35.235.240.0/20"]
}
